define("mod_seledascorm/reporting_dashboard",[],function(){return {init:function(){document.querySelectorAll("[data-rpt-submit]").forEach(function(f){f.addEventListener("change",function(){if(f.dataset.rptSubmit==="course")f.form.elements.id.value="0";var g=f.form.elements.group;if(g)g.value="0";f.form.requestSubmit();});});}};});
